'use strict';
const C=CampusCore,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
let state,storageError='',message='',query='',activeDay=0;
try{state=C.load(localStorage);}catch(e){state=C.seed();storageError=e.message;}
const registered=()=>C.courses.filter(c=>state.registered.includes(c.id));
const units=()=>registered().reduce((s,c)=>s+c.units,0);
function session(){try{return Number(sessionStorage.getItem('campus.session'))>Date.now();}catch{return false;}}
function persist(next){if(storageError)throw Error('Resolve the saved-data issue in Settings first.');try{state=C.save(localStorage,next);}catch{throw Error('Could not save your change. Browser storage may be full or blocked. Your previous data is unchanged.');}}
function flash(text){message=text;renderPortal(false);}
function action(fn){if(!session()){renderPortal();return;}try{fn();}catch(e){flash(e.message);}}
function shell(route){document.querySelector('header').innerHTML=`<a class="brand" href="#dashboard"><span class="mark">c.</span>campus</a><nav aria-label="Main navigation">${[['dashboard','Dashboard'],['courses','Courses'],['timetable','Timetable'],['results','Results'],['notifications','Inbox'],['profile','Profile']].map(([id,label])=>`<a href="#${id}" ${route===id?'aria-current="page" class="active"':''}>${label}${id==='notifications'?` <span class="count">${state.notices.filter(n=>!state.read.includes(n.id)).length}</span>`:''}</a>`).join('')}</nav><button class="quiet" id="logout">Sign out</button>`;document.querySelector('footer').innerHTML='<a class="brand" href="#dashboard">campus.</a><div class="footer-links"><a href="#overview">Architecture study</a><a href="#about">Creators</a><a href="#settings">Settings</a></div><span>Sample records · Saved on this browser</span>';document.querySelector('#logout').onclick=()=>{sessionStorage.removeItem('campus.session');message='Signed out. Your demo records are saved on this browser.';renderPortal();};}
const heading=(label,title,sub)=>`<div class="portal-heading"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p>${sub}</p></div><span class="badge">2026 / 27 · First semester</span></div>`;
const courseRow=(c,control='')=>`<article class="course-row"><div class="course-code">${c.id.slice(0,3)}<b>${c.id.slice(3)}</b></div><div class="course-info"><h3>${esc(c.title)}</h3><p>${c.units} units · ${days[c.day]} ${c.start}:00–${c.end}:00 · ${esc(c.room)}</p></div>${control}</article>`;
function dashboard(){const today=registered().filter(c=>c.day===new Date().getDay());return `${heading('Your student workspace',`Hello, ${esc(state.profile.name.split(' ')[0])}.`,'Your semester, all in one place.')}<div class="portal-metrics">${[['Registered courses',state.registered.length,'courses','Manage courses'],['Semester units',units()+' / 18','timetable','View your week'],['Unread updates',state.notices.filter(n=>!state.read.includes(n.id)).length,'notifications','Open inbox']].map(x=>`<article><span>${x[0]}</span><strong>${x[1]}</strong><a href="#${x[2]}">${x[3]} →</a></article>`).join('')}</div><div class="portal-columns"><section class="panel"><div class="panel-title"><h2>Today’s classes</h2><span>${days[new Date().getDay()]}</span></div>${today.length?today.map(c=>courseRow(c)).join(''):'<div class="empty"><h3>A little breathing room.</h3><p>No registered classes today.</p><a class="text-link" href="#timetable">View timetable →</a></div>'}</section><section class="blue-panel"><div class="eyebrow">Build your semester</div><h2>Make room for<br>what’s next.</h2><p>Browse courses, review prerequisites, and register up to 18 units.</p><a class="primary" href="#courses">Register courses ↗</a></section></div><section class="panel"><div class="panel-title"><h2>Your courses</h2><a class="text-link" href="#courses">Manage →</a></div>${registered().map(c=>courseRow(c)).join('')||'<p>No courses registered yet.</p>'}</section>`;}
function catalogue(){return C.courses.filter(c=>!state.registered.includes(c.id)&&`${c.id} ${c.title}`.toLowerCase().includes(query.toLowerCase())).map(c=>`<label class="catalogue-item"><input type="checkbox" data-select="${c.id}" ${state.draft.includes(c.id)?'checked':''}><div><b>${c.id} · ${esc(c.title)}</b><p>${c.units} units · ${days[c.day]} ${c.start}:00–${c.end}:00</p>${c.required?`<span class="fine">Prerequisite: previously pass ${c.required}</span>`:''}</div></label>`).join('')||'<p class="empty">No available courses match your search.</p>';}
function coursesPage(){const selected=state.draft.filter(id=>!state.registered.includes(id)),error=C.validate([...state.registered,...selected]);return `${heading('Registration','Shape your semester.','Changes update your saved demo registration and timetable immediately.')}<div class="course-layout"><section><div class="panel"><h2>Registered <span class="badge">${state.registered.length}</span></h2>${registered().map(c=>courseRow(c,`<button class="quiet danger" data-drop="${c.id}" aria-label="Drop ${c.id}">Drop</button>`)).join('')||'<p>No courses registered.</p>'}</div><div class="panel"><h2>Course catalogue</h2><label for="course-search">Find a course</label><input id="course-search" type="search" placeholder="Course code or title" value="${esc(query)}"><div id="catalogue">${catalogue()}</div></div></section><aside class="panel registration-summary"><div class="eyebrow">Registration summary</div><h2>${units()+selected.reduce((s,id)=>s+(C.courses.find(c=>c.id===id)?.units||0),0)} <span class="muted">/ 18 units</span></h2><p>${selected.length} courses selected</p>${selected.map(id=>`<div class="selection">${esc(id)}<button class="quiet" data-unselect="${esc(id)}" aria-label="Remove ${esc(id)} from selection">×</button></div>`).join('')}${error?`<p class="form-error" role="alert">${error}</p>`:''}<button class="primary full" id="register" ${!selected.length||error?'disabled':''}>Confirm registration</button><p class="fine">Demo only. No request is sent to a university. Your selection is saved while you navigate.</p></aside></div>`;}
function timetable(){return `${heading('Your weekly schedule','A clearer week ahead.','Your timetable follows your registered courses. Saved data is available offline.')}<div class="toolbar"><div class="tabs day-tabs">${['All week',...days.slice(1,6)].map((d,i)=>`<button data-day="${i}" aria-pressed="${activeDay===i}" class="${activeDay===i?'chosen':''}">${d}</button>`).join('')}</div><button class="quiet" id="export-calendar">Export calendar</button></div><div class="week-grid">${[1,2,3,4,5].filter(d=>!activeDay||d===activeDay).map(d=>`<section class="day-column"><h2>${days[d]}</h2>${registered().filter(c=>c.day===d).sort((a,b)=>a.start-b.start).map(c=>`<article class="class-card"><span>${c.start}:00–${c.end}:00</span><h3>${c.id}</h3><p>${c.title}</p><small>${c.room}</small></article>`).join('')||'<p class="free-day">No classes</p>'}</section>`).join('')}</div><p class="fine">Last saved: ${new Date(state.updatedAt).toLocaleString()} · Calendar export covers 12 teaching weeks beginning 28 September 2026 (Africa/Lagos).</p>`;}
function resultsPage(){const total=C.results.reduce((s,r)=>s+r.units,0),points=C.results.reduce((s,r)=>s+C.grade(r.score)[1]*r.units,0);return `${heading('Academic results','Your progress, in view.','Sample results for the previous semester. These are demonstration records.')}<section class="result-banner"><div><span>Semester GPA · 5.0 scale</span><strong>${(points/total).toFixed(2)}</strong></div><div><span>Completed units</span><strong>${total}</strong></div><button class="quiet" id="export-results">Download results CSV</button></section><section class="panel table-wrap"><table><thead><tr><th>Course</th><th>Units</th><th>Score</th><th>Grade</th><th>Grade points</th></tr></thead><tbody>${C.results.map(r=>`<tr><td><strong>${r.id}</strong><br>${r.title}</td><td>${r.units}</td><td>${r.score}</td><td><span class="badge">${C.grade(r.score)[0]}</span></td><td>${C.grade(r.score)[1]*r.units}</td></tr>`).join('')}</tbody></table><p class="fine">GPA = weighted grade points ÷ units. A: 70–100 (5), B: 60–69 (4), C: 50–59 (3), D: 45–49 (2), E: 40–44 (1), F: below 40 (0).</p></section>`;}
function inbox(){return `${heading('Notifications','Stay in the loop.','Registration updates and sample university announcements.')}<div class="toolbar"><h2>${state.notices.filter(n=>!state.read.includes(n.id)).length} unread</h2><button class="quiet" id="read-all">Mark all as read</button></div><section class="panel">${state.notices.map(n=>`<article class="notice ${state.read.includes(n.id)?'read':''}"><div><span class="fine">${new Date(n.date).toLocaleDateString()}</span><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p></div><button class="quiet" data-read="${esc(n.id)}">${state.read.includes(n.id)?'Mark unread':'Mark read'}</button></article>`).join('')}</section>`;}
function profilePage(){return `${heading('Your profile','Make yourself at home.','Update your demo contact details. Academic information is read-only.')}<div class="portal-columns"><form id="profile-form" class="panel"><h2>Personal information</h2>${[['name','Full name','text',80],['email','Email address','email',120],['phone','Phone number (optional)','tel',20]].map(([id,label,type,max])=>`<label for="${id}">${label}</label><input id="${id}" name="${id}" type="${type}" maxlength="${max}" ${id!=='phone'?'required':''} value="${esc(state.profile[id])}">`).join('')}<button class="primary" type="submit">Save changes</button></form><section class="panel"><div class="eyebrow">Academic details</div><h2>${esc(state.profile.department)}</h2><dl><dt>Student ID</dt><dd>${esc(state.profile.studentId)}</dd><dt>Level</dt><dd>${esc(state.profile.level)}</dd><dt>Session</dt><dd>2026 / 2027</dd></dl><p class="fine">This is a sample profile. Use sample contact details when exploring.</p></section></div>`;}
function settings(){return `${heading('Preferences & session','Your workspace settings.','This demo stores records on this browser. It does not sync across devices.')}<div class="portal-columns"><section class="panel"><h2>Appearance</h2><label for="theme">Theme</label><select id="theme"><option value="light">Light</option><option value="dark">Dark</option><option value="system">Follow system</option></select><h2 style="margin-top:32px">Demo session</h2><p>Sessions last 30 minutes in this tab. This demonstrates expiry, not secure university authentication.</p><button class="quiet" id="expire">Expire session now</button></section><section class="panel"><h2>Your saved data</h2><p>Registration, drafts, profile edits, and read status survive navigation and refresh. Other tabs in this browser receive updates. The most recent save wins.</p><button class="quiet" id="export-data">Export demo data</button><hr><h3>Start again</h3><p>Reset courses, notifications, and the profile to the sample values.</p><button class="quiet danger" id="reset">Reset demo data</button></section></div>`;}
function login(){document.querySelector('header').innerHTML='<a class="brand" href="#dashboard"><span class="mark">c.</span>campus</a><span class="badge">Interactive demo</span>';document.querySelector('main').innerHTML=`<div class="login-layout"><section><div class="eyebrow">Your student workspace</div><h1>Campus life.<br><em>Under control.</em></h1><p class="lead">Manage your courses, plan your week, and keep track of what matters.</p></section><form class="panel" id="login-form"><span class="badge">Sample student account</span><h2 style="margin-top:25px">Welcome to Campus.</h2><p>Open a working demo with sample records. No password or university account is needed.</p>${message?`<p role="status">${esc(message)}</p>`:''}<button class="primary full">Enter demo workspace →</button><p class="fine">Saved on this browser. Sessions expire after 30 minutes. This is not connected to university systems.</p></form></div>`;document.querySelector('#login-form').onsubmit=e=>{e.preventDefault();try{sessionStorage.setItem('campus.session',String(Date.now()+30*60*1000));message='';if(!location.hash||location.hash==='#overview')location.hash='dashboard';else renderPortal();}catch{message='Enable browser storage to open the demo.';login();}};}
function renderPortal(scroll=true){let route=location.hash.slice(1)||'dashboard';shell(route);if(!session()){login();return;}if(['overview','architectures','recommendation','scenarios','about'].includes(route)){studyRender();return;}const pages={dashboard,courses:coursesPage,timetable,results:resultsPage,notifications:inbox,profile:profilePage,settings};if(!pages[route])route='dashboard';document.title=`${route[0].toUpperCase()+route.slice(1)} — Campus`;document.querySelector('main').innerHTML=`<div class="connectivity" id="connection">${navigator.onLine?'Demo workspace · changes saved on this browser':'Offline · your saved courses and timetable are available'}</div><div class="wrap portal">${storageError?`<div class="feedback error" role="alert">${esc(storageError)} <a href="#settings">Open Settings</a></div>`:''}${message?`<div class="feedback" role="status">${esc(message)}<button class="quiet" id="dismiss" aria-label="Dismiss message">×</button></div>`:''}${pages[route]()}</div><dialog id="confirm-dialog" aria-labelledby="confirm-title" aria-describedby="confirm-description"><h2 id="confirm-title"></h2><p id="confirm-description"></p><div class="actions"><button class="quiet" id="cancel-confirm">Cancel</button><button class="primary" id="accept-confirm">Confirm</button></div></dialog>`;bind();if(scroll)window.scrollTo(0,0);}
function confirmAction(title,description,fn){const d=document.querySelector('#confirm-dialog');document.querySelector('#confirm-title').textContent=title;document.querySelector('#confirm-description').textContent=description;document.querySelector('#cancel-confirm').onclick=()=>d.close();document.querySelector('#accept-confirm').onclick=()=>{d.close();action(fn);};d.showModal();}
function bindCatalogue(){document.querySelectorAll('[data-select]').forEach(el=>el.onchange=()=>action(()=>{persist({...state,draft:el.checked?[...new Set([...state.draft,el.dataset.select])]:state.draft.filter(x=>x!==el.dataset.select)});renderPortal(false);}));}
function bind(){const on=(id,fn)=>{const el=document.querySelector('#'+id);if(el)el.onclick=()=>action(fn);};on('dismiss',()=>{message='';renderPortal(false);});on('register',()=>{persist(C.register(state,state.draft));flash('Registration saved. Your timetable has been updated.');});bindCatalogue();document.querySelectorAll('[data-unselect]').forEach(el=>el.onclick=()=>action(()=>{persist({...state,draft:state.draft.filter(id=>id!==el.dataset.unselect)});renderPortal(false);}));document.querySelectorAll('[data-drop]').forEach(el=>el.onclick=()=>confirmAction(`Drop ${el.dataset.drop}?`,'This removes the course from your demo registration and timetable. You can register it again.',()=>{persist(C.drop(state,el.dataset.drop));flash('Course dropped. Timetable updated.');}));const search=document.querySelector('#course-search');if(search)search.oninput=()=>{query=search.value;document.querySelector('#catalogue').innerHTML=catalogue();bindCatalogue();};document.querySelectorAll('[data-day]').forEach(el=>el.onclick=()=>{activeDay=+el.dataset.day;renderPortal(false);});document.querySelectorAll('[data-read]').forEach(el=>el.onclick=()=>action(()=>{const id=el.dataset.read;persist({...state,read:state.read.includes(id)?state.read.filter(x=>x!==id):[...state.read,id]});renderPortal(false);}));on('read-all',()=>{persist({...state,read:state.notices.map(n=>n.id)});flash('All notifications marked as read.');});const form=document.querySelector('#profile-form');if(form)form.onsubmit=e=>{e.preventDefault();action(()=>{persist(C.profile(state,Object.fromEntries(new FormData(form))));flash('Profile changes saved.');});};on('export-results',()=>download('campus-sample-results.csv','Course,Title,Units,Score,Grade\n'+C.results.map(r=>`${r.id},${r.title},${r.units},${r.score},${C.grade(r.score)[0]}`).join('\n'),'text/csv'));on('export-calendar',exportCalendar);on('export-data',()=>download('campus-demo-data.json',localStorage.getItem('campus.data.v1')||JSON.stringify(state,null,2),'application/json'));on('expire',()=>{sessionStorage.removeItem('campus.session');message='Your demo session has expired. Reopen the workspace to continue; saved data is still here.';renderPortal();});on('reset',()=>confirmAction('Reset demo data?','Your profile edits, registrations, drafts, and read status will be replaced with sample records.',()=>{state=C.save(localStorage,C.seed());storageError='';flash('Demo data reset.');}));const theme=document.querySelector('#theme');if(theme){try{theme.value=localStorage.getItem('campus.theme')||'light';}catch{}theme.onchange=()=>{try{localStorage.setItem('campus.theme',theme.value);applyTheme();}catch{flash('Could not save theme preference.');}};}}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCalendar(){const rows=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Campus Demo//Timetable//EN'];for(const c of registered()){const date=new Date(Date.UTC(2026,8,27+c.day)).toISOString().slice(0,10).replace(/-/g,'');rows.push('BEGIN:VEVENT',`UID:${c.id}-2026@campus.demo`,'DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),`DTSTART:${date}T${String(c.start-1).padStart(2,'0')}0000Z`,`DTEND:${date}T${String(c.end-1).padStart(2,'0')}0000Z`,'RRULE:FREQ=WEEKLY;COUNT=12',`SUMMARY:${c.id} - ${c.title}`,`LOCATION:${c.room}`,'END:VEVENT');}rows.push('END:VCALENDAR');download('campus-timetable.ics',rows.join('\r\n'),'text/calendar');}
function applyTheme(){let theme='light';try{theme=localStorage.getItem('campus.theme')||'light';}catch{}document.documentElement.dataset.theme=theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):theme;}
window.addEventListener('hashchange',()=>{message='';renderPortal();});window.addEventListener('storage',e=>{if(e.key==='campus.data.v1'){try{state=C.load(localStorage);flash('Updated from another tab.');}catch{flash('Could not load changes from another tab.');}}if(e.key==='campus.theme')applyTheme();});window.addEventListener('online',()=>renderPortal(false));window.addEventListener('offline',()=>renderPortal(false));setInterval(()=>{if(!session()&&document.querySelector('#logout')){message='Your session has expired. Reopen the demo to continue.';renderPortal();}},10000);matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applyTheme);applyTheme();renderPortal();if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{const el=document.querySelector('#connection');if(el)el.textContent+=' · Offline app loading could not be enabled';});
